  "termsScreen": {
    "paragraph1": "Sabiን በመጠቀም የቦርሳ ባህሪያት፣ ግንኙነቶች፣ ግብይቶች እና ዲጂታል አገልግሎቶችን ለመጠቀም የተወሰኑ የመድረኩን ህጎች፣ ተፈጻሚ ህጎችን እና የደህንነት መስፈርቶችን ለመከተል ተስማምተዋል።",
    "paragraph2": "ተጠቃሚው የቀረበው መረጃ ትክክለኛነት፣ የግል መሣሪያዎቹ ጥበቃ፣ ወደ መለያው የሚደረግ መዳረሻ ቁጥጥር እና በስርዓቱ ውስጥ የሚፈጸሙ ተግባራት ሕጋዊነት ላይ ኃላፊነት ይወስዳል።",
    "paragraph3": "Sabi ምርቱን ለማሻሻል፣ የቁጥጥር መስፈርቶችን ለማሟላት እና ተጠቃሚዎችን ለመጠበቅ ባህሪያትን፣ የደህንነት መስፈርቶችን፣ የአጠቃቀም ህጎችን እና የተለያዩ የአገልግሎት ውሎችን ማዘመን ይችላል።",
    "paragraph4": "ውሎች ከተዘመኑ በኋላ መድረኩን መቀጠል የአገልግሎት ህጎችን በአሁኑ እትም መቀበል ማለት ነው።"
  },
  "privacyPolicyScreen": {
    "paragraph1": "Sabiን በመጠቀም የቦርሳ ባህሪያት፣ ግንኙነቶች፣ ግብይቶች እና ዲጂታል አገልግሎቶችን ለመጠቀም የተወሰኑ የመድረኩን ህጎች፣ ተፈጻሚ ህጎችን እና የደህንነት መስፈርቶችን ለመከተል ተስማምተዋል።",
    "paragraph2": "ተጠቃሚው የቀረበው መረጃ ትክክለኛነት፣ የግል መሣሪያዎቹ ጥበቃ፣ ወደ መለያው የሚደረግ መዳረሻ ቁጥጥር እና በስርዓቱ ውስጥ የሚፈጸሙ ተግባራት ሕጋዊነት ላይ ኃላፊነት ይወስዳል።",
    "paragraph3": "Sabi ምርቱን ለማሻሻል፣ የቁጥጥር መስፈርቶችን ለማሟላት እና ተጠቃሚዎችን ለመጠበቅ ባህሪያትን፣ የደህንነት መስፈርቶችን፣ የአጠቃቀም ህጎችን እና የተለያዩ የአገልግሎት ውሎችን ማዘመን ይችላል።",
    "paragraph4": "ውሎች ከተዘመኑ በኋላ መድረኩን መቀጠል የአገልግሎት ህጎችን በአሁኑ እትም መቀበል ማለት ነው።"
  },
